CREATE TABLE IF NOT EXISTS advisor_performance_status (advisor_id TEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'GREEN' CHECK (status IN ('GREEN','YELLOW','RED','REMEDIATION','CLOSED')), score INTEGER, status_reason TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS advisor_performance_rules (id TEXT PRIMARY KEY, rule_code TEXT NOT NULL UNIQUE, description TEXT NOT NULL, threshold_value INTEGER, threshold_unit TEXT, severity TEXT NOT NULL CHECK (severity IN ('YELLOW','RED')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS advisor_issue_cases (id TEXT PRIMARY KEY, advisor_id TEXT NOT NULL, category TEXT NOT NULL, summary TEXT NOT NULL, advisor_response TEXT, status TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','UNDER_REVIEW','RESOLVED','CLOSED')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS advisor_remediation_plans (id TEXT PRIMARY KEY, advisor_id TEXT NOT NULL, issue_case_id TEXT, issue_summary TEXT NOT NULL, required_actions TEXT NOT NULL, support_offered TEXT, review_start TEXT NOT NULL, review_end TEXT NOT NULL, outcome TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','COMPLETED','EXTENDED','CANCELLED')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS advisor_notifications (id TEXT PRIMARY KEY, advisor_id TEXT NOT NULL, channel TEXT NOT NULL CHECK (channel IN ('EMAIL','SMS','IN_APP')), notification_type TEXT NOT NULL, message_template TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'QUEUED' CHECK (status IN ('QUEUED','SENT','FAILED','ACKNOWLEDGED')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, sent_at TEXT);
CREATE TABLE IF NOT EXISTS advisor_status_events (id TEXT PRIMARY KEY, advisor_id TEXT NOT NULL, event_type TEXT NOT NULL, previous_status TEXT, new_status TEXT, source TEXT NOT NULL DEFAULT 'SYSTEM', metadata_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_perf_status ON advisor_performance_status(status);
CREATE INDEX IF NOT EXISTS idx_issue_advisor_status ON advisor_issue_cases(advisor_id, status);
CREATE INDEX IF NOT EXISTS idx_remediation_advisor_status ON advisor_remediation_plans(advisor_id, status);
CREATE INDEX IF NOT EXISTS idx_notifications_advisor_status ON advisor_notifications(advisor_id, status);
CREATE INDEX IF NOT EXISTS idx_status_events_advisor_created ON advisor_status_events(advisor_id, created_at);
